    out = nl.ndarray((P, F), dtype=x.dtype, buffer=nl.shared_hbm)

    # Allocate a tile for the data
    tile = nl.ndarray((128, 128), dtype=x.dtype, buffer=nl.sbuf)

    # Load data into the tile
    for p in nl.affine_range(P):
        for f1 in nl.affine_range(F1):
            for f2 in nl.affine_range(F2):
                tile[f1, f2] = x[p, f1 * F2 + f2]

    # Transpose the tile
    transposed_tile = nl.ndarray((F2, F1), dtype=x.dtype, buffer=nl.psum)
    for f1 in nl.affine_range(F1):
        for f2 in nl.affine_range(F2):
            transposed_tile[f2, f1] = tile[f1, f2]

    # Copy result back to shared HBM
    for p in nl.affine_range(P):
        for f1 in nl.affine_range(F1):
            for f2 in nl.affine_range(F2):
                out[p, f1 * F2 + f2] = transposed_tile[f1, f2]

    return out

